27	const TASK_LINE_REGEXP = /^(\s*)((?:[-*+])|(?:\d+[.)]))(\s+)\[([ xX])\]/;
28	
29	function getLineStarts(markdown: string): number[] {
30	  const starts = [0];
31	  for (let index = 0; index < markdown.length; index++) {
32	    if (markdown[index] === "\n") {
33	      starts.push(index + 1);
34	    }
35	  }
36	  return starts;
37	}
38	
39	function getLineInfo(markdown: string, lineStarts: number[], lineNumber: number): LineInfo | undefined {
40	  const startOffset = lineStarts[lineNumber];
41	  if (startOffset === undefined) {
42	    return undefined;
43	  }
44	
45	  const nextLineStart = lineStarts[lineNumber + 1];
46	  const endOffset = nextLineStart === undefined ? markdown.length : nextLineStart - 1;
47	  return {
48	    text: markdown.slice(startOffset, endOffset),
49	    startOffset,
50	    endOffset,
51	  };
52	}
53	
54	function parseMarkdown(markdown: string) {
55	  return fromMarkdown(markdown, {
56	    extensions: [gfm()],
57	    mdastExtensions: [gfmFromMarkdown()],
58	  });
59	}
