106	function applyMarkdownEdits(markdown: string, edits: MarkdownEdit[]): string {
107	  if (edits.length === 0) {
108	    return markdown;
109	  }
110	
111	  const sortedEdits = [...edits].sort((a, b) => a.start - b.start);
112	  let previousEnd = 0;
113	  for (const edit of sortedEdits) {
114	    if (edit.start < 0 || edit.end < edit.start || edit.end > markdown.length || edit.start < previousEnd) {
115	      return markdown;
116	    }
117	    previousEnd = edit.end;
118	  }
119	
120	  let nextMarkdown = markdown;
121	  for (let index = sortedEdits.length - 1; index >= 0; index--) {
122	    const edit = sortedEdits[index];
123	    nextMarkdown = `${nextMarkdown.slice(0, edit.start)}${edit.replacement}${nextMarkdown.slice(edit.end)}`;
124	  }
125	  return nextMarkdown;
126	}
